import csv,math,numpy as np
from functools import reduce
from scipy.optimize import minimize
r=list(csv.DictReader(open('responses.csv')))
rows=[]
for x in r:
    xs=[int(a) for a in x['number_set'].split(',')];t=int(x['target']);rows.append((xs,t,int(x['rating'])))
Y=np.array([y for _,_,y in rows])
def feats(w,mode):
    out=[]
    for xs,t,_ in rows:
        n=len(xs)
        sd=sum(a%10==t%10 for a in xs)/n; sp=sum(a%2==t%2 and a%10!=t%10 for a in xs)/n
        g=reduce(math.gcd,xs); cf=float(g>=3 and t%g==0)
        if mode=='dec': e=sum(math.exp(-abs(a//10-t//10)/w) for a in xs)/n
        elif mode=='mag': e=sum(math.exp(-abs(a-t)/w) for a in xs)/n
        elif mode=='maxdec': e=max(math.exp(-abs(a//10-t//10)/w) for a in xs)
        out.append([sd,sp,cf,e])
    return np.array(out)
for mode in ['dec','maxdec','mag']:
  for w in ([0.3,1,2,4] if mode!='mag' else [5,10,20,40]):
    F=feats(w,mode)
    def nll(p):
        z=p[0]+p[1]*(F[:,0]+p[2]*F[:,1])+p[3]*F[:,2]+p[4]*F[:,3]
        return -np.sum(Y*z-np.logaddexp(0,z))
    res=minimize(nll,np.zeros(5)+0.1,method='BFGS');print(mode,w,round(res.fun,1),res.x.round(2))
"

